import React, { useEffect, useState, useRef, useCallback } from "react";
import EmojiPicker from "emoji-picker-react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import { io } from "socket.io-client";
import { useAuth } from "../context/AuthContext";
import "./Chat.css";

let socket;

export default function Chat() {
  const { userId } = useParams();
  const { user } = useAuth();
  const navigate = useNavigate();

  const [conversations, setConversations] = useState([]);
  const [messages, setMessages] = useState([]);
  const [activeUser, setActiveUser] = useState(null);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [convLoading, setConvLoading] = useState(true);
  const [showEmoji, setShowEmoji] = useState(false);
  const [uploading, setUploading] = useState(false);

  const bottomRef = useRef(null);
  const activeUserRef = useRef(null);
  const fileInputRef = useRef(null);

  useEffect(() => {
    activeUserRef.current = activeUser;
  }, [activeUser]);

  useEffect(() => {
    socket = io("http://localhost:5000");
    socket.emit("join", user._id.toString());

    socket.on("receiveMessage", ({ senderId, message, timestamp }) => {
      const activeConvUserId = activeUserRef.current?._id;

      if (
        activeConvUserId &&
        activeConvUserId.toString() === senderId.toString()
      ) {
        setMessages((prev) => [
          ...prev,
          {
            sender: { _id: senderId },
            content: message,
            createdAt: timestamp,
          },
        ]);
      }

      setConversations((prev) => {
        const exists = prev.find(
          (c) => c.partner._id.toString() === senderId.toString()
        );

        if (exists) {
          return prev.map((c) =>
            c.partner._id.toString() === senderId.toString()
              ? {
                  ...c,
                  lastMessage: { content: message, createdAt: timestamp },
                }
              : c
          );
        }

        axios
          .get("/api/messages/conversations")
          .then((res) => setConversations(res.data));

        return prev;
      });
    });

    return () => socket.disconnect();
  }, [user._id]);

  const loadConversations = useCallback(async () => {
    try {
      const { data } = await axios.get("/api/messages/conversations");
      setConversations(data);
    } catch (err) {
      console.error(err);
    } finally {
      setConvLoading(false);
    }
  }, []);

  useEffect(() => {
    loadConversations();
  }, [loadConversations]);

  const openConversation = useCallback(
    async (targetUser) => {
      if (!targetUser?._id) return;

      setActiveUser(targetUser);
      setShowEmoji(false);
      setLoading(true);

      navigate("/chat/" + targetUser._id, { replace: true });

      try {
        const { data } = await axios.get(
          "/api/messages/" + targetUser._id
        );
        setMessages(data);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    },
    [navigate]
  );

  useEffect(() => {
    if (!userId) return;

    axios
      .get("/api/users/" + userId)
      .then((res) => openConversation(res.data))
      .catch(() => {});
  }, [userId, openConversation]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const onEmojiClick = (emojiData) => {
    setInput((prev) => prev + emojiData.emoji);
    setShowEmoji(false);
  };

  const uploadFile = async (file) => {
    if (!activeUser) return;

    setUploading(true);

    const formData = new FormData();
    formData.append("file", file);
    formData.append("receiverId", activeUser._id.toString());

    try {
      const { data } = await axios.post(
        "/api/messages/upload",
        formData
      );

      setMessages((prev) => [...prev, data]);

      socket.emit("sendMessage", {
        senderId: user._id.toString(),
        receiverId: activeUser._id.toString(),
        message: data.content,
      });
    } catch (err) {
      console.error(err);
    } finally {
      setUploading(false);
    }
  };

  const sendMessage = async () => {
    if (!input.trim() || !activeUser) return;

    const content = input.trim();
    setInput("");

    const timestamp = new Date();

    setMessages((prev) => [
      ...prev,
      { sender: { _id: user._id }, content, createdAt: timestamp },
    ]);

    try {
      await axios.post("/api/messages/send", {
        receiverId: activeUser._id,
        content,
      });

      socket.emit("sendMessage", {
        senderId: user._id.toString(),
        receiverId: activeUser._id.toString(),
        message: content,
      });
    } catch (err) {
      console.error(err);
    }
  };

  const renderMessage = (msg, i) => {
    const isMe =
      msg.sender?._id?.toString() === user._id?.toString();

    let content;

    if (msg.type === "image" && msg.fileUrl) {
      content = (
        <div>
          <img
            src={msg.fileUrl}
            alt=""
            style={{ maxWidth: "220px" }}
          />
          <div>{msg.fileName}</div>
        </div>
      );
    } else if (msg.type === "file" && msg.fileUrl) {
      content = (
        <a href={msg.fileUrl} target="_blank" rel="noreferrer">
          📎 {msg.fileName}
        </a>
      );
    } else {
      content = <span>{msg.content}</span>;
    }

    return (
      <div key={i} className={isMe ? "me" : "them"}>
        {content}
      </div>
    );
  };

  return (
  <div className="chat-page">

    {/* SIDEBAR */}
    <div className="chat-sidebar">
      <div className="chat-sidebar-header">Messages</div>

      {conversations.map((c) => (
        <div
          key={c.partner._id}
          className={
            "conv-item " +
            (activeUser?._id === c.partner._id ? "active" : "")
          }
          onClick={() => openConversation(c.partner)}
        >
          {c.partner.name}
        </div>
      ))}
    </div>

    {/* MAIN CHAT */}
    <div className="chat-main">

      {/* HEADER */}
      <div className="chat-header">
        {activeUser ? activeUser.name : "Select a chat"}
      </div>

      {/* MESSAGES */}
      <div className="messages-area">
        {messages.map((msg, i) => renderMessage(msg, i))}
        <div ref={bottomRef} />
      </div>

      {/* INPUT */}
      <div className="chat-input-area">

        <button
          className="btn-outline"
          onClick={() => setShowEmoji((p) => !p)}
        >
          😊
        </button>

        {showEmoji && <EmojiPicker onEmojiClick={onEmojiClick} />}

        <input
          type="file"
          ref={fileInputRef}
          onChange={(e) => uploadFile(e.target.files[0])}
        />

        <textarea
          className="chat-input"
          value={input}
          onChange={(e) => setInput(e.target.value)}
        />

        <button className="btn-primary" onClick={sendMessage}>
          Send
        </button>

      </div>
    </div>
  </div>
);
}
